const req = $('When Executed by Another Workflow').first().json;
const emp = $input.first().json;

const QUERIES = {
  stock_by_product: { roles: ['staff','manager'], view: 'v_stock_staff',       needsDates: false },
  low_stock:        { roles: ['staff','manager'], view: 'v_stock_staff',       needsDates: false },
  expiring_batches: { roles: ['staff','manager'], view: 'v_batches_staff',     needsDates: true  },
  sales_summary:    { roles: ['staff','manager'], view: 'v_sales_staff',       needsDates: true  },
  purchase_status:  { roles: ['staff','manager'], view: 'v_purchases_staff',   needsDates: false },
  sales_profit:     { roles: ['manager'],         view: 'v_sales_manager',     needsDates: true  },
  purchase_costs:   { roles: ['manager'],         view: 'v_purchases_manager', needsDates: false }
};
const STATUSES = ['ordered','received','delayed','cancelled'];
const isDate = s => /^\d{4}-\d{2}-\d{2}$/.test(s) && !isNaN(new Date(s));

const q = String(req.query_name || '').trim();
const def = QUERIES[q];
const from = String(req.date_from || '').trim();
const to = String(req.date_to || '').trim();
const status = String(req.status || '').trim().toLowerCase();
const product = String(req.product_name || '').trim().slice(0, 60);

let role = 'none';
if (emp.employee_id && emp.employment_status === 'active') {
  role = String(emp.job_title || '').toLowerCase() === 'manager' ? 'manager' : 'staff';
}

let allowed = true, reason = '';
if (role === 'none') { allowed = false; reason = 'Could not verify the employee.'; }
else if (!def) { allowed = false; reason = 'Unsupported query. Supported: ' + Object.keys(QUERIES).join(', '); }
else if (!def.roles.includes(role)) { allowed = false; reason = 'Your role does not have access to this information.'; }
else if (def.needsDates && (!isDate(from) || !isDate(to) || from > to)) { allowed = false; reason = 'A valid date range is required (YYYY-MM-DD, start not after end).'; }
else if (def.needsDates && (new Date(to) - new Date(from)) / 86400000 > 366) { allowed = false; reason = 'Date range too long (max 366 days).'; }
else if (status && !STATUSES.includes(status)) { allowed = false; reason = 'Unknown status. Use: ' + STATUSES.join(', '); }

return [{ json: { allowed, reason, role, query_name: q, view: def ? def.view : null,
                  product_name: product,
                  date_from: def && def.needsDates ? from : '',
                  date_to: def && def.needsDates ? to : '',
                  status,
                  debug_received: JSON.stringify(req) } }];

const ctx = $('Authorize').first().json;
const q = ctx.query_name;
let rows = $input.all().map(i => i.json);

if (ctx.product_name) {
  const t = ctx.product_name.toLowerCase();
  rows = rows.filter(r => String(r.name || '').toLowerCase().includes(t) ||
                          String(r.product_id || '').toLowerCase() === t);
}
if (q === 'low_stock') rows = rows.filter(r => r.is_low_stock === true);
if (q === 'expiring_batches') rows = rows.filter(r => r.expiry_date >= ctx.date_from && r.expiry_date <= ctx.date_to);
if (q === 'sales_summary' || q === 'sales_profit') rows = rows.filter(r => r.sale_date >= ctx.date_from && r.sale_date <= ctx.date_to);
if ((q === 'purchase_status' || q === 'purchase_costs') && ctx.status) rows = rows.filter(r => r.status === ctx.status);

const n = x => Number(x || 0);
const sum = k => rows.reduce((s, r) => s + n(r[k]), 0);
let totals = null;
if (q === 'sales_summary') totals = { units: sum('quantity'), revenue: sum('revenue') };
if (q === 'sales_profit')  totals = { units: sum('quantity'), revenue: sum('revenue'), profit: sum('profit') };

const d = v => String(v).slice(0, 10);
if (q === 'expiring_batches') rows = rows.filter(r => d(r.expiry_date) >= ctx.date_from && d(r.expiry_date) <= ctx.date_to);
if (q === 'sales_summary' || q === 'sales_profit') rows = rows.filter(r => d(r.sale_date) >= ctx.date_from && d(r.sale_date) <= ctx.date_to);

return [{ json: {
  query: q, role: ctx.role, source: ctx.view,
  period: ctx.date_from ? `${ctx.date_from} to ${ctx.date_to}` : 'current data',
  row_count: rows.length, truncated: rows.length > 40, totals, rows: rows.slice(0, 40)
} }];
